const fs = require('fs');
const body = ($input.first().json.body) || {};
const runId = String(body.run || new Date().toISOString().slice(0, 16).replace(':', ''));
if (!/^[A-Za-z0-9._-]{1,40}$/.test(runId)) throw new Error('run id may only use letters, digits, dot, dash and underscore');
const mode = body.mode === 'dry run' ? 'dry run' : 'live';
const only = Array.isArray(body.sources) ? body.sources : null;
const dir = '/files/sources';
const sources = fs.readdirSync(dir).filter((file) => file.endsWith('.json')).sort().map((file) => {
  try { return JSON.parse(fs.readFileSync(dir + '/' + file, 'utf8')); }
  catch (error) { return { id: file.replace(/\.json$/, ''), name: file, brokenFile: error.message }; }
});
const picked = sources.filter((s) => (only ? only.includes(s.id) : s.enabled !== false));
if (!picked.length) throw new Error('no sources to run' + (only ? ': ' + only.join(', ') : ''));
fs.mkdirSync('/files/output/runs/' + runId, { recursive: true });
return picked.map((s) => ({ json: { runId, mode, source: s } }));

// Feed parsers. Each returns { rows: [{ row, raw }] } or throws FeedError, so a broken
// feed stops that source before anything is compared or written.

class FeedError extends Error {}

function decodeEntities(text) {
  return text
    .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, (_, inner) => inner)
    .replace(/&#x([0-9a-f]+);/gi, (_, hex) => String.fromCodePoint(parseInt(hex, 16)))
    .replace(/&#(\d+);/g, (_, dec) => String.fromCodePoint(Number(dec)))
    .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&apos;/g, "'")
    .replace(/&amp;/g, '&');
}

// Flat record XML: <root><record><field>value</field>…</record>…</root>. Attributes on the
// record element become fields too (for example <listing ref="NG-101">).
function parseXml(text, recordTag) {
  const body = String(text || '').replace(/<\?xml[\s\S]*?\?>/, '').replace(/<!--[\s\S]*?-->/g, '').trim();
  if (!body.startsWith('<')) throw new FeedError('not an XML document');
  const opened = (body.match(new RegExp(`<${recordTag}[\\s>]`, 'g')) || []).length;
  const closed = (body.match(new RegExp(`</${recordTag}>`, 'g')) || []).length;
  if (opened !== closed) throw new FeedError(`XML is cut off or malformed: ${opened} <${recordTag}> opened, ${closed} closed`);
  const rows = [];
  const recordPattern = new RegExp(`<${recordTag}((?:\\s+[\\w:-]+="[^"]*")*)\\s*>([\\s\\S]*?)</${recordTag}>`, 'g');
  let match;
  while ((match = recordPattern.exec(body))) {
    const raw = {};
    for (const [, name, value] of match[1].matchAll(/([\w:-]+)="([^"]*)"/g)) raw[name] = decodeEntities(value);
    for (const [, name, value] of match[2].matchAll(/<([\w:-]+)(?:\s[^>]*)?>([\s\S]*?)<\/\1>/g)) raw[name] = decodeEntities(value).trim();
    for (const [, name] of match[2].matchAll(/<([\w:-]+)(?:\s[^>]*)?\/>/g)) if (!(name in raw)) raw[name] = '';
    rows.push({ row: rows.length + 1, raw });
  }
  if (opened && rows.length !== opened) throw new FeedError(`could not read ${opened - rows.length} of ${opened} <${recordTag}> records`);
  return { rows };
}

// RFC 4180 CSV with a header row. Quoted fields may contain the delimiter, quotes ("") and newlines.
function parseCsv(text, delimiter = ',') {
  const source = String(text || '').replace(/^﻿/, '');
  const records = [];
  let field = '';
  let record = [];
  let quoted = false;
  for (let i = 0; i < source.length; i += 1) {
    const char = source[i];
    if (quoted) {
      if (char === '"' && source[i + 1] === '"') { field += '"'; i += 1; }
      else if (char === '"') quoted = false;
      else field += char;
    } else if (char === '"' && field === '') quoted = true;
    else if (char === delimiter) { record.push(field); field = ''; }
    else if (char === '\n' || char === '\r') {
      if (char === '\r' && source[i + 1] === '\n') i += 1;
      record.push(field); field = '';
      if (record.some((value) => value !== '')) records.push(record);
      record = [];
    } else field += char;
  }
  if (quoted) throw new FeedError('CSV ends inside a quoted field');
  record.push(field);
  if (record.some((value) => value !== '')) records.push(record);
  if (!records.length) return { rows: [] };
  const headers = records[0].map((name) => name.trim());
  const rows = records.slice(1).map((values, index) => {
    if (values.length !== headers.length) return { row: index + 1, raw: {}, shapeError: `has ${values.length} columns, header has ${headers.length}` };
    return { row: index + 1, raw: Object.fromEntries(headers.map((name, column) => [name, values[column].trim()])) };
  });
  return { rows, headers };
}

function getPath(value, path) {
  return String(path).split('.').reduce((current, key) => (current == null ? undefined : current[key]), value);
}

// JSON API response: records live at `recordPath` (dot path), each an object.
function parseJson(text, recordPath) {
  let data;
  try { data = JSON.parse(text); } catch (error) { throw new FeedError(`not valid JSON (${error.message})`); }
  const list = recordPath ? getPath(data, recordPath) : data;
  if (!Array.isArray(list)) throw new FeedError(`no list found at "${recordPath}"`);
  return { rows: list.map((raw, index) => ({ row: index + 1, raw: raw && typeof raw === 'object' ? raw : {} })) };
}

function parseFeed(text, source) {
  if (source.format === 'xml') return parseXml(text, source.record);
  if (source.format === 'csv') return parseCsv(text, source.delimiter || ',');
  if (source.format === 'json') return parseJson(text, source.record);
  throw new FeedError(`unknown feed format "${source.format}"`);
}

// Turns one operator's raw feed row into the marketplace's listing shape, using that
// operator's mapping file (sources/<id>.json). Everything operator-specific lives in the
// mapping file; this code is the same for every source.
// Needs getPath from parse.js (inlined before this file in the n8n Code node).

const UNIT_TYPES = ['locker', 'small', 'medium', 'large', 'parking'];
const FEED_STATUSES = ['available', 'rented', 'withdrawn'];
const SQFT_TO_M2 = 0.09290304;

function text(value) {
  return value == null ? '' : String(value).trim();
}

// "$1,249.50", "1.249,50 €" (decimal ","), "129" → number. Returns NaN when it isn't a number.
// A thousands separator must be followed by exactly three digits, so "1,8" with decimal "."
// is rejected instead of silently read as 18.
function parseNumber(value, decimal = '.') {
  const cleaned = text(value).replace(/[^\d.,-]/g, '');
  if (!cleaned) return NaN;
  const group = decimal === ',' ? '\\.' : ',';
  const point = decimal === ',' ? ',' : '\\.';
  if (!new RegExp(`^-?(\\d{1,3}(${group}\\d{3})+|\\d+)(${point}\\d+)?$`).test(cleaned)) return NaN;
  return Number(cleaned.replace(new RegExp(group, 'g'), '').replace(',', '.'));
}

function lookup(map, value) {
  if (!map) return value;
  const key = Object.keys(map).find((candidate) => candidate.toLowerCase() === value.toLowerCase());
  return key === undefined ? undefined : map[key];
}

function mapRow(raw, source) {
  const f = source.fields;
  const read = (name) => (f[name] ? text(getPath(raw, f[name])) : '');
  const values = source.values || {};
  const units = source.units || {};
  const problems = [];
  const problem = (field, issue, rawValue) => problems.push({ field, problem: issue, raw: rawValue });

  const externalRef = read('external_ref');
  if (!externalRef) problem('external_ref', 'missing external ref', '');
  const title = read('title');
  if (!title) problem('title', 'missing title', '');

  const rawType = read('unit_type');
  const unitType = lookup(values.unit_type, rawType);
  if (!rawType) problem('unit_type', 'missing unit type', '');
  else if (!UNIT_TYPES.includes(unitType)) problem('unit_type', 'unknown unit type', rawType);

  const rawSize = read('size');
  let size = parseNumber(rawSize, source.decimal);
  if (units.size === 'sqft') size = Math.round(size * SQFT_TO_M2 * 10) / 10;
  if (!rawSize) problem('size', 'missing size', '');
  else if (!(size > 0)) problem('size', 'size is not a positive number', rawSize);

  const rawPrice = read('monthly_price');
  const price = parseNumber(rawPrice, source.decimal);
  if (!rawPrice) problem('monthly_price', 'missing price', '');
  else if (!(price > 0)) problem('monthly_price', 'price is not a positive number', rawPrice);

  const rawStatus = read('status');
  const status = lookup(values.status, rawStatus);
  if (!rawStatus) problem('status', 'missing status', '');
  else if (!FEED_STATUSES.includes(status)) problem('status', 'unknown status', rawStatus);

  const rawClimate = read('climate_controlled');
  const climate = rawClimate ? lookup(values.climate_controlled || { yes: true, no: false, true: true, false: false }, rawClimate) : false;
  if (typeof climate !== 'boolean') problem('climate_controlled', 'not yes or no', rawClimate);

  const imageUrl = read('image_url');
  if (imageUrl && !/^https:\/\/[^\s]+$/.test(imageUrl)) problem('image_url', 'image link is not https', imageUrl);

  return {
    problems,
    listing: {
      external_ref: externalRef,
      title,
      unit_type: unitType,
      size_m2: size,
      monthly_price: Math.round(price * 100) / 100,
      area: read('area'),
      climate_controlled: climate === true,
      image_url: imageUrl,
      status,
    },
  };
}

// Checks a mapping file before it is used, so a typo fails loudly instead of skipping fields.
function checkSource(source) {
  const issues = [];
  for (const name of ['id', 'name', 'format', 'url', 'fields']) if (!source[name]) issues.push(`missing "${name}"`);
  if (source.format && !['xml', 'csv', 'json'].includes(source.format)) issues.push(`format must be xml, csv or json, not "${source.format}"`);
  if (source.format === 'xml' && !source.record) issues.push('xml sources need "record" (the record element name)');
  if (source.id && !/^[a-z][a-z0-9-]{1,30}$/.test(source.id)) issues.push('id must be lowercase letters, digits or dashes');
  for (const name of ['external_ref', 'title', 'unit_type', 'size', 'monthly_price', 'status']) {
    if (!source.fields || !source.fields[name]) issues.push(`fields.${name} is required`);
  }
  for (const [value, mapped] of Object.entries((source.values || {}).unit_type || {})) {
    if (!UNIT_TYPES.includes(mapped)) issues.push(`values.unit_type maps "${value}" to "${mapped}", which is not one of ${UNIT_TYPES.join(', ')}`);
  }
  for (const [value, mapped] of Object.entries((source.values || {}).status || {})) {
    if (!FEED_STATUSES.includes(mapped)) issues.push(`values.status maps "${value}" to "${mapped}", which is not one of ${FEED_STATUSES.join(', ')}`);
  }
  return issues;
}

// Compares one source's feed with what the marketplace already has and decides every write.
// Needs parse.js and map.js inlined before it. Pure: no network, so the rules are unit tested.

const STATUS_FOR = { available: 'Active', rented: 'Closed', withdrawn: 'Closed' };
const CLOSE_REASON_FOR = { rented: 'Rented', withdrawn: 'Withdrawn' };
const DEFAULT_SAFETY = { min_ratio: 0.5, min_active: 5 };

function listingKey(sourceId, ref) {
  return `${sourceId}:${ref}`;
}

function contentHash(listing) {
  const ordered = ['external_ref', 'title', 'unit_type', 'size_m2', 'monthly_price', 'area', 'climate_controlled', 'image_url', 'status'];
  const payload = JSON.stringify(ordered.map((name) => listing[name]));
  return sha1Hex(payload).slice(0, 16);
}

// Plain-JS SHA-1 (same output as crypto's) so the Code node needs no require(); n8n Cloud allows none.
function sha1Hex(text) {
  const bytes = Array.from(unescape(encodeURIComponent(text)), (c) => c.charCodeAt(0));
  const bitLength = bytes.length * 8;
  bytes.push(0x80);
  while (bytes.length % 64 !== 56) bytes.push(0);
  for (let shift = 56; shift >= 0; shift -= 8) bytes.push(Math.floor(bitLength / 2 ** shift) & 0xff);
  const rotl = (n, s) => (n << s) | (n >>> (32 - s));
  let [h0, h1, h2, h3, h4] = [0x67452301, 0xefcdab89, 0x98badcfe, 0x10325476, 0xc3d2e1f0];
  const w = new Array(80);
  for (let offset = 0; offset < bytes.length; offset += 64) {
    for (let i = 0; i < 16; i++) w[i] = (bytes[offset + i * 4] << 24) | (bytes[offset + i * 4 + 1] << 16) | (bytes[offset + i * 4 + 2] << 8) | bytes[offset + i * 4 + 3];
    for (let i = 16; i < 80; i++) w[i] = rotl(w[i - 3] ^ w[i - 8] ^ w[i - 14] ^ w[i - 16], 1);
    let [a, b, c, d, e] = [h0, h1, h2, h3, h4];
    for (let i = 0; i < 80; i++) {
      const [f, k] = i < 20 ? [(b & c) | (~b & d), 0x5a827999] : i < 40 ? [b ^ c ^ d, 0x6ed9eba1] : i < 60 ? [(b & c) | (b & d) | (c & d), 0x8f1bbcdc] : [b ^ c ^ d, 0xca62c1d6];
      const t = (rotl(a, 5) + f + e + k + w[i]) | 0;
      [e, d, c, b, a] = [d, c, rotl(b, 30), a, t];
    }
    [h0, h1, h2, h3, h4] = [(h0 + a) | 0, (h1 + b) | 0, (h2 + c) | 0, (h3 + d) | 0, (h4 + e) | 0];
  }
  return [h0, h1, h2, h3, h4].map((h) => (h >>> 0).toString(16).padStart(8, '0')).join('');
}

function emptySummary(feedRows = 0) {
  return { feedRows, created: 0, updated: 0, unchanged: 0, closed: 0, reopened: 0, restored: 0, held: 0, rowErrors: 0, ignored: 0 };
}

// fetchResult: { statusCode, body, error }  existing: [{ id, fields }] for this source only.
function planSync({ source, fetchResult, existing, runId, mode = 'live' }) {
  const safety = { ...DEFAULT_SAFETY, ...(source.safety || {}) };
  const result = { source: source.id, runId, mode, outcome: 'OK', summary: emptySummary(), writes: [], rowErrors: [], alerts: [], notes: [] };
  const stop = (reason) => {
    result.outcome = 'Feed unavailable';
    result.notes.push(`${reason}. Nothing was changed for ${source.id}; listings stay as they were.`);
    result.alerts.push(`:warning: ${source.name}: feed not used this run (${reason}). No listings were closed.`);
    return result;
  };

  const configIssues = checkSource(source);
  if (configIssues.length) {
    result.outcome = 'Mapping file error';
    result.notes.push(`${source.configLabel || `sources/${source.id}.json`}: ${configIssues.join('; ')}`);
    result.alerts.push(`:warning: ${source.name}: mapping file has problems, source skipped: ${configIssues.join('; ')}`);
    return result;
  }
  if (fetchResult.error) return stop(`could not fetch feed: ${fetchResult.error}`);
  if (fetchResult.statusCode !== 200) return stop(`feed answered HTTP ${fetchResult.statusCode}`);
  if (!String(fetchResult.body || '').trim()) return stop('feed was empty');

  let parsed;
  try {
    parsed = parseFeed(fetchResult.body, source);
  } catch (error) {
    if (error instanceof FeedError) return stop(`feed could not be read: ${error.message}`);
    throw error;
  }
  const rows = parsed.rows;
  result.summary.feedRows = rows.length;
  if (!rows.length) return stop('feed had no records');

  // Map every row; collect problems per row.
  const mapped = rows.map((entry) => {
    if (entry.shapeError) return { row: entry.row, listing: { external_ref: '' }, problems: [{ field: '(row)', problem: entry.shapeError, raw: '' }] };
    const { listing, problems } = mapRow(entry.raw, source);
    return { row: entry.row, listing, problems };
  });

  // The same ref twice is ambiguous: reject every copy and leave the current listing alone.
  const rowsByRef = new Map();
  for (const item of mapped) {
    if (!item.listing.external_ref) continue;
    rowsByRef.set(item.listing.external_ref, [...(rowsByRef.get(item.listing.external_ref) || []), item.row]);
  }
  for (const item of mapped) {
    const copies = rowsByRef.get(item.listing.external_ref) || [];
    if (copies.length > 1) item.problems.push({ field: 'external_ref', problem: `same ref on rows ${copies.join(' and ')}`, raw: item.listing.external_ref });
  }

  // A ref that is in the feed, even on a broken row, is not "missing".
  const seenRefs = new Set(mapped.map((item) => item.listing.external_ref).filter(Boolean));
  const byKey = new Map(existing.map((record) => [record.fields['Listing key'], record]));
  const live = (record) => ['Active', 'Pending removal'].includes(record.fields.Status);
  const activeBefore = existing.filter(live).length;

  for (const item of mapped) {
    if (item.problems.length) {
      result.summary.rowErrors += 1;
      for (const issue of item.problems) {
        result.rowErrors.push({ ref: item.listing.external_ref || '', row: item.row, field: issue.field, problem: issue.problem, raw: String(issue.raw ?? '') });
      }
      continue;
    }
    const listing = item.listing;
    const key = listingKey(source.id, listing.external_ref);
    const hash = contentHash(listing);
    const status = STATUS_FOR[listing.status];
    const current = byKey.get(key);
    const fields = {
      'Listing key': key, Source: source.id, 'External ref': listing.external_ref, Title: listing.title,
      'Unit type': listing.unit_type, 'Size m2': listing.size_m2, 'Monthly price': listing.monthly_price, Area: listing.area,
      'Climate controlled': listing.climate_controlled, 'Image URL': listing.image_url || null,
      Status: status, 'Close reason': CLOSE_REASON_FOR[listing.status] || null, 'Content hash': hash, 'Last changed run': runId,
    };

    if (!current) {
      if (status !== 'Active') { result.summary.ignored += 1; continue; }
      result.writes.push({ ...fields, 'First seen run': runId });
      result.summary.created += 1;
      continue;
    }
    const was = current.fields.Status;
    if (current.fields['Content hash'] === hash && was === status) { result.summary.unchanged += 1; continue; }
    result.writes.push(fields);
    if (was === 'Closed' && status === 'Active') result.summary.reopened += 1;
    else if (was === 'Pending removal' && status === 'Active') result.summary.restored += 1;
    else if (was !== 'Closed' && status === 'Closed') result.summary.closed += 1;
    else result.summary.updated += 1;
  }

  // Listings the feed no longer has. If the feed suddenly shrank, hold instead of closing.
  const missing = existing.filter((record) => live(record) && !seenRefs.has(record.fields['External ref']));
  const shrank = activeBefore >= safety.min_active && rows.length < safety.min_ratio * activeBefore;
  if (missing.length && shrank) {
    result.outcome = 'Removals held';
    for (const record of missing) {
      if (record.fields.Status !== 'Pending removal') result.writes.push({ 'Listing key': record.fields['Listing key'], Status: 'Pending removal', 'Last changed run': runId });
      result.summary.held += 1;
    }
    const note = `feed has ${rows.length} rows but ${activeBefore} listings are live (below ${Math.round(safety.min_ratio * 100)}%). ${missing.length} missing listings marked Pending removal, not closed`;
    result.notes.push(note);
    result.alerts.push(`:warning: ${source.name}: ${note}. Check the feed before releasing them.`);
  } else {
    for (const record of missing) {
      result.writes.push({ 'Listing key': record.fields['Listing key'], Status: 'Closed', 'Close reason': 'Missing from feed', 'Last changed run': runId });
      result.summary.closed += 1;
    }
  }

  if (result.summary.ignored) result.notes.push(`${result.summary.ignored} new row(s) not available yet, so not listed`);
  if (result.summary.rowErrors) {
    if (result.outcome === 'OK') result.outcome = 'OK with row errors';
    const first = result.rowErrors.slice(0, 3).map((error) => `${error.ref || 'row ' + error.row}: ${error.problem}${error.raw ? ` ("${error.raw}")` : ''}`);
    result.alerts.push(`:memo: ${source.name}: ${result.summary.rowErrors} row(s) skipped, the rest synced. ${first.join('; ')}${result.rowErrors.length > 3 ? '; …' : ''}`);
  }
  if (mode === 'dry run') {
    result.notes.push(`dry run: ${result.writes.length} write(s) planned, none made`);
    result.alerts = [];
  }
  return result;
}

// Records for the Sync Runs and Row Errors tables.
function runRecords(plan) {
  const s = plan.summary;
  const run = {
    Run: `${plan.runId}/${plan.source}`, Source: plan.source, Mode: plan.mode, Outcome: plan.outcome,
    'Rows in feed': s.feedRows, Created: s.created, Updated: s.updated, Unchanged: s.unchanged, Closed: s.closed,
    Reopened: s.reopened, Restored: s.restored, Held: s.held, 'Row errors': s.rowErrors, Notes: plan.notes.join('\n'),
  };
  const errors = plan.rowErrors.map((error, index) => ({
    Error: `${plan.runId}/${plan.source}/${index + 1}`, Run: `${plan.runId}/${plan.source}`, Source: plan.source,
    'External ref': error.ref, Row: error.row, Field: error.field, Problem: error.problem, 'Raw value': error.raw,
  }));
  return { run, errors };
}

function chunk(list, size = 10) {
  const out = [];
  for (let i = 0; i < list.length; i += size) out.push(list.slice(i, i + size));
  return out;
}

const fs = require('fs');
const job = $('Each source').first().json;
const response = $('Fetch feed').first().json;
const fetchResult = response.error
  ? { error: String(response.error.message || response.error).slice(0, 200) }
  : (() => {
      // With responseFormat "text" n8n puts the body in `data`; keep `body` as a fallback.
      const raw = response.data !== undefined ? response.data : response.body;
      return { statusCode: response.statusCode, body: raw == null ? '' : (typeof raw === 'string' ? raw : JSON.stringify(raw)) };
    })();
const existing = $input.all().flatMap((item) => item.json.records || []);
const plan = job.source.brokenFile
  ? { source: job.source.id, runId: job.runId, mode: job.mode, outcome: 'Mapping file error', summary: { feedRows: 0, created: 0, updated: 0, unchanged: 0, closed: 0, reopened: 0, restored: 0, held: 0, rowErrors: 0, ignored: 0 }, writes: [], rowErrors: [], notes: ['sources/' + job.source.id + '.json is not valid JSON: ' + job.source.brokenFile], alerts: [':warning: ' + job.source.id + ': mapping file is not valid JSON, source skipped'] }
  : planSync({ source: job.source, fetchResult, existing, runId: job.runId, mode: job.mode });
const { run, errors } = runRecords(plan);
fs.writeFileSync('/files/output/runs/' + job.runId + '/' + job.source.id + '.json', JSON.stringify({ ...plan, existingBefore: existing.length }, null, 2), 'utf8');

// One item per Airtable request, in order: listings first, then the run log.
const requests = [];
if (plan.mode === 'live') {
  for (const batch of chunk(plan.writes, 10)) requests.push({ method: 'PATCH', table: 'Listings', body: { performUpsert: { fieldsToMergeOn: ['Listing key'] }, typecast: true, records: batch.map((fields) => ({ fields })) } });
}
requests.push({ method: 'POST', table: 'Sync Runs', body: { typecast: true, records: [{ fields: run }] } });
for (const batch of chunk(errors, 10)) requests.push({ method: 'POST', table: 'Row Errors', body: { typecast: true, records: batch.map((fields) => ({ fields })) } });
return requests.map((request) => ({ json: request }));

const job = $('Each source').first().json;
const plan = JSON.parse(require('fs').readFileSync('/files/output/runs/' + job.runId + '/' + job.source.id + '.json', 'utf8'));
return [{ json: { source: plan.source, outcome: plan.outcome, alerts: plan.alerts } }];

const fs = require('fs');
const runId = $('Load sources').first().json.runId;
const dir = '/files/output/runs/' + runId;
const plans = $('Load sources').all().map((item) => JSON.parse(fs.readFileSync(dir + '/' + item.json.source.id + '.json', 'utf8')));
const cols = ['feedRows', 'created', 'updated', 'unchanged', 'closed', 'reopened', 'restored', 'held', 'rowErrors'];
const lines = ['Run ' + runId + ' (' + plans[0].mode + ')', '', 'source      outcome              ' + cols.join(' ')];
for (const p of plans) lines.push(p.source.padEnd(12) + p.outcome.padEnd(21) + cols.map((c) => String(p.summary[c]).padStart(c.length)).join(' '));
for (const p of plans) for (const n of p.notes) lines.push('  ' + p.source + ': ' + n);
const report = { runId, mode: plans[0].mode, sources: plans.map((p) => ({ source: p.source, outcome: p.outcome, summary: p.summary, notes: p.notes, rowErrors: p.rowErrors })) };
fs.writeFileSync(dir + '/report.txt', lines.join('\n') + '\n', 'utf8');
fs.writeFileSync(dir + '/report.json', JSON.stringify(report, null, 2), 'utf8');
return [{ json: report }];
